"""Build the prespecified compact IM-R4 result and audit package."""
from __future__ import annotations
import argparse,csv,hashlib,json,math
from pathlib import Path
from typing import Any
import yaml

def read_csv(path:Path)->list[dict[str,str]]:
    with path.open(newline='',encoding='utf-8') as f:return list(csv.DictReader(f))
def write_csv(path:Path,rows:list[dict[str,Any]],fields:list[str]|None=None):
    if not rows:raise ValueError(f'empty output: {path}')
    path.parent.mkdir(parents=True,exist_ok=True); fields=fields or list(rows[0])
    with path.open('w',newline='',encoding='utf-8') as f:w=csv.DictWriter(f,fieldnames=fields); w.writeheader(); w.writerows(rows)
def sha(path:Path)->str:
    h=hashlib.sha256()
    with path.open('rb') as f:
        for c in iter(lambda:f.read(1024*1024),b''):h.update(c)
    return h.hexdigest()
def f(row,key):return float(row[key])
def subset(rows,**filters):return [r for r in rows if all(r[k]==str(v) for k,v in filters.items())]
def write_json(path,payload):path.write_text(json.dumps(payload,indent=2,sort_keys=True)+'\n',encoding='utf-8')

def build(full_dir:Path,output:Path,repro_check:Path|None=None)->dict[str,Any]:
    output.mkdir(parents=True,exist_ok=True)
    rows=read_csv(full_dir/'pooled_cell_summary.csv'); audit=json.loads((full_dir/'full_simulation_audit.json').read_text()); convergence=json.loads((full_dir/'stream_convergence_audit.json').read_text())
    spec={
      'schema_version':'1.0','phase':'IM-R4','status':'materialisation of selections already fixed by the frozen IM-R3 protocol','source_protocol_sha256':audit['protocol_sha256'],'source_pooled_summary_sha256':audit['pooled_cell_summary_sha256'],
      'reference_process':{'allocation_profile':'balanced','misclassification_profile':'none','missingness_profile':'none'},
      'reference_sample_size_per_group':250,
      'sample_size_trace':[50,100,250,500],
      'observation_process_subset':{'sample_size_per_group':250,'allocation_profile':'balanced','include_all_misclassification_profiles':True,'include_all_missingness_profiles':True},
      'figure_data':{
        'Figure_4':'reference process; all six scenarios and four sample sizes; mean broad-minus-active Cramers V with mean MCSE',
        'Figure_5':'reference process; all six scenarios and four sample sizes; probability of any strict cross-definition reversal with event MCSE',
        'Figure_S2':'n=250 balanced; all observation-process profiles; active and broad association observation error',
        'Figure_S3':'all 432 cells; undefined association fraction and frozen warning/no-claim thresholds'},
      'interpretive_boundaries':['No p-values across simulation cells or replications.','No quality ranking from the sign of delta V.','Sample rank reversals under a generating population tie are instability, not population reversal.','The simulation is conditional on the frozen mechanisms and is not empirical prevalence evidence.','Managerial decision-quality claims require a separate decision model or experiment.']}
    spec_path=output/'im_r4_reporting_specification.yml'; spec_path.write_text(yaml.safe_dump(spec,sort_keys=False,allow_unicode=True),encoding='utf-8'); spec_hash=sha(spec_path); write_json(output/'im_r4_reporting_specification.lock.json',{'schema_version':'1.0','specification_path':spec_path.name,'specification_sha256':spec_hash,'source_protocol_sha256':audit['protocol_sha256'],'note':'The selections are direct materialisations of the reporting order and figure plan frozen before full results.'})
    scenarios=['null_same_mixture','aligned_gradient','project_only_gradient','compensating_gradient','rank_reversal','mixed_order']
    reference=[]
    for s in scenarios:
        r=subset(rows,scenario=s,sample_size_per_group=250,allocation_profile='balanced',misclassification_profile='none',missingness_profile='none')[0]
        reference.append({'scenario':s,'population_active_cramers_v':r['population_active_cramers_v'],'population_broad_cramers_v':r['population_broad_cramers_v'],'population_delta_cramers_v':r['population_delta_cramers_v'],'mean_observed_delta_cramers_v':r['mean_delta_cramers_v_broad_minus_active'],'mcse_mean_observed_delta_cramers_v':r['mean_mcse_delta_cramers_v_broad_minus_active'],'probability_broad_association_stronger':r['probability_broad_association_stronger'],'mcse_broad_association_stronger':r['mcse_broad_association_stronger'],'probability_any_order_disagreement':r['probability_any_cross_definition_order_disagreement'],'mcse_any_order_disagreement':r['mcse_any_cross_definition_order_disagreement'],'probability_any_strict_reversal':r['probability_any_cross_definition_strict_reversal'],'mcse_any_strict_reversal':r['mcse_any_cross_definition_strict_reversal'],'mean_project_share_of_broad_positive':r['mean_project_share_of_broad_positive'],'mcse_mean_project_share':r['mean_mcse_project_share_of_broad_positive']})
    write_csv(output/'reference_process_n250.csv',reference)
    trace=[]
    for s in scenarios:
      for n in (50,100,250,500):
        r=subset(rows,scenario=s,sample_size_per_group=n,allocation_profile='balanced',misclassification_profile='none',missingness_profile='none')[0]
        trace.append({'scenario':s,'sample_size_per_group':n,'population_delta_cramers_v':r['population_delta_cramers_v'],'mean_observed_delta_cramers_v':r['mean_delta_cramers_v_broad_minus_active'],'mcse_mean_observed_delta_cramers_v':r['mean_mcse_delta_cramers_v_broad_minus_active'],'probability_broad_association_stronger':r['probability_broad_association_stronger'],'probability_any_order_disagreement':r['probability_any_cross_definition_order_disagreement'],'probability_any_strict_reversal':r['probability_any_cross_definition_strict_reversal'],'mcse_any_strict_reversal':r['mcse_any_cross_definition_strict_reversal']})
    write_csv(output/'reference_process_by_sample_size.csv',trace)
    observation=[]
    obs_rows=subset(rows,sample_size_per_group=250,allocation_profile='balanced')
    for r in obs_rows:
      observation.append({'scenario':r['scenario'],'misclassification_profile':r['misclassification_profile'],'missingness_profile':r['missingness_profile'],'mean_delta_cramers_v':r['mean_delta_cramers_v_broad_minus_active'],'probability_broad_association_stronger':r['probability_broad_association_stronger'],'probability_any_strict_reversal':r['probability_any_cross_definition_strict_reversal'],'mean_active_level_observation_error':r['mean_active_level_observation_error'],'mean_broad_level_observation_error':r['mean_broad_level_observation_error'],'mean_active_association_observation_error':r['mean_active_association_observation_error'],'mean_broad_association_observation_error':r['mean_broad_association_observation_error'],'undefined_association_fraction':r['undefined_association_fraction']})
    write_csv(output/'observation_process_n250_balanced.csv',observation)
    undefined=[{'cell_id':r['cell_id'],'scenario':r['scenario'],'sample_size_per_group':r['sample_size_per_group'],'allocation_profile':r['allocation_profile'],'misclassification_profile':r['misclassification_profile'],'missingness_profile':r['missingness_profile'],'undefined_active_association_fraction':r['undefined_active_association_fraction'],'undefined_broad_association_fraction':r['undefined_broad_association_fraction'],'undefined_association_fraction':r['undefined_association_fraction']} for r in rows]
    write_csv(output/'undefined_association_audit.csv',undefined)
    conv_rows=read_csv(full_dir/'stream_convergence.csv'); warnings=[r for r in conv_rows if r['status']!='PASS'];
    if warnings:write_csv(output/'stream_convergence_nonpass.csv',warnings)
    # Figure-ready data; figures are produced only after manuscript-table selection is locked.
    write_csv(output/'figure_4_reference_delta_v_data.csv',[{'scenario':r['scenario'],'sample_size_per_group':r['sample_size_per_group'],'mean_delta_cramers_v_broad_minus_active':r['mean_observed_delta_cramers_v'],'mean_mcse_delta_cramers_v_broad_minus_active':r['mcse_mean_observed_delta_cramers_v']} for r in trace])
    write_csv(output/'figure_5_reference_strict_reversal_data.csv',[{'scenario':r['scenario'],'sample_size_per_group':r['sample_size_per_group'],'probability_any_cross_definition_strict_reversal':r['probability_any_strict_reversal'],'mcse_any_cross_definition_strict_reversal':r['mcse_any_strict_reversal']} for r in trace])
    write_csv(output/'figure_s2_observation_error_data.csv',[{'scenario':r['scenario'],'observation_profile':r['misclassification_profile']+'__'+r['missingness_profile'],'mean_active_association_observation_error':r['mean_active_association_observation_error'],'mean_broad_association_observation_error':r['mean_broad_association_observation_error']} for r in observation])
    write_csv(output/'figure_s3_undefined_audit_data.csv',[{'cell_index':i,'undefined_association_fraction':r['undefined_association_fraction'],'warning_threshold':0.01,'no_claim_threshold':0.05} for i,r in enumerate(undefined)])
    # Core numerical checks and scientifically meaningful contrasts.
    ref={r['scenario']:r for r in reference}; obs={(r['scenario'],r['misclassification_profile'],r['missingness_profile']):r for r in observation}
    checks={
      'aligned_population_delta_positive':float(ref['aligned_gradient']['population_delta_cramers_v'])>0,
      'project_only_population_active_zero':abs(float(ref['project_only_gradient']['population_active_cramers_v']))<1e-12,
      'compensating_population_broad_zero':abs(float(ref['compensating_gradient']['population_broad_cramers_v']))<1e-12,
      'rank_reversal_population_delta_negative':float(ref['rank_reversal']['population_delta_cramers_v'])<0,
      'rank_reversal_sample_strict_reversal_probability_one':abs(float(ref['rank_reversal']['probability_any_strict_reversal'])-1)<1e-12,
      'within_broad_swap_preserves_broad_level_rank_reversal':abs(float(obs[('rank_reversal','active_project_swap_10','none')]['mean_broad_level_observation_error']))<1e-12,
      'within_broad_swap_preserves_broad_association_rank_reversal':abs(float(obs[('rank_reversal','active_project_swap_10','none')]['mean_broad_association_observation_error']))<1e-12,
      'boundary_crossing_swap_changes_broad_association_rank_reversal':abs(float(obs[('rank_reversal','project_other_swap_10','none')]['mean_broad_association_observation_error']))>0.05,
      'no_undefined_primary_associations':max(float(r['undefined_association_fraction']) for r in rows)==0,
      'event_mcse_meets_frozen_target':float(audit['maximum_event_probability_mcse'])<=float(audit['event_probability_mcse_target']),
      'nested_level_violations_zero':int(audit['nested_level_violation_count'])==0,
      'convergence_failures_zero':int(audit['convergence_failure_count'])==0,
    }
    reproducible=None
    if repro_check and repro_check.exists():reproducible=json.loads(repro_check.read_text())['all_identical']
    checks['independent_full_rerun_core_outputs_byte_identical']=bool(reproducible)
    gate='GO' if all(checks.values()) else 'NO-GO'
    gate_payload={'phase':'IM-R4','status':'COMPLETE','gate':gate,'full_simulation_status':audit['status'],'protocol_sha256':audit['protocol_sha256'],'reporting_specification_sha256':spec_hash,'cell_count':audit['cell_count'],'replications_per_cell':audit['replications_per_cell'],'replicate_row_count':audit['replicate_row_count'],'stream_count':audit['stream_count'],'maximum_event_probability_mcse':audit['maximum_event_probability_mcse'],'maximum_standardised_stream_deviation':audit['maximum_standardised_stream_deviation'],'convergence_warning_count':audit['convergence_warning_count'],'convergence_failure_count':audit['convergence_failure_count'],'undefined_warning_cell_count':audit['undefined_warning_cell_count'],'undefined_no_claim_cell_count':audit['undefined_no_claim_cell_count'],'nested_level_violation_count':audit['nested_level_violation_count'],'core_rerun_byte_identical':bool(reproducible),'checks':checks,'open_scientific_gates':['independent Study 2','article reconstruction','ethics determination','article-code-table-figure parity','final release and Zenodo DOI'],'submission_gate':'NO-GO'}
    write_json(output/'IM_R4_GATE.json',gate_payload)
    ledger=[
      {'claim_id':'SIM-C01','claim':'For nested definitions, the broader level never fell below the narrower level in any replicate.','evidence':'full_simulation_audit.json','status':'SUPPORTED','boundary':'Arithmetic invariant under a common observed denominator.'},
      {'claim_id':'SIM-C02','claim':'Nested outcome broadening did not constrain the sign of the association contrast.','evidence':'reference_process_n250.csv; reference_process_by_sample_size.csv','status':'SUPPORTED','boundary':'Conditional on the six frozen mechanisms and Cramers V.'},
      {'claim_id':'SIM-C03','claim':'Strict subgroup-order reversals can occur under nested outcome definitions.','evidence':'rank_reversal scenario in reference_process_n250.csv','status':'SUPPORTED','boundary':'Population reversal is encoded only in the rank_reversal mechanism; tie-driven sample instability must be distinguished.'},
      {'claim_id':'SIM-C04','claim':'Misclassification confined within the broad positive set can alter the narrow association while preserving the broad boundary.','evidence':'observation_process_n250_balanced.csv','status':'SUPPORTED','boundary':'Exact for the active/project swap under no missingness in the frozen three-state design.'},
      {'claim_id':'SIM-C05','claim':'Boundary-crossing misclassification can alter the broad outcome level and association.','evidence':'observation_process_n250_balanced.csv','status':'SUPPORTED','boundary':'Conditional on the symmetric 10 per cent project/other profile.'},
      {'claim_id':'SIM-C06','claim':'ODSA improves managerial decisions.','evidence':'none','status':'NOT SUPPORTED','boundary':'Requires a separate decision model or prospective experiment.'},
      {'claim_id':'SIM-C07','claim':'The simulated probabilities are universal properties of ODSA.','evidence':'none','status':'PROHIBITED','boundary':'All frequencies are conditional on the frozen design.'},
    ]; write_csv(output/'IM_R4_CLAIM_EVIDENCE_LEDGER.csv',ledger)
    summary=f'''# IM-R4 full simulation — manuscript-ready numerical summary\n\n## Design and integrity\n\nThe frozen design contained 432 cells and was executed through four independently spawned streams with 1,000 replications per stream and cell. The pooled evidence therefore comprises 4,000 replications per cell and 1,728,000 replicate rows. The maximum event-probability Monte Carlo standard error was {float(audit['maximum_event_probability_mcse']):.6f}, below the frozen target of {float(audit['event_probability_mcse_target']):.3f}. No primary association was undefined and no nested-level violation occurred. A second complete execution reproduced all core matrices and summaries byte-for-byte.\n\n## Reference process at n = 250 per group\n\n- Aligned gradient: population ΔV = {float(ref['aligned_gradient']['population_delta_cramers_v']):.6f}; mean observed ΔV = {float(ref['aligned_gradient']['mean_observed_delta_cramers_v']):.6f}.\n- Project-only gradient: active-use population V = 0 and broad-engagement population V = {float(ref['project_only_gradient']['population_broad_cramers_v']):.6f}; mean observed ΔV = {float(ref['project_only_gradient']['mean_observed_delta_cramers_v']):.6f}.\n- Compensating gradient: broad-engagement population V = 0 while active-use population V = {float(ref['compensating_gradient']['population_active_cramers_v']):.6f}; mean observed ΔV = {float(ref['compensating_gradient']['mean_observed_delta_cramers_v']):.6f}.\n- Rank-reversal mechanism: population ΔV = {float(ref['rank_reversal']['population_delta_cramers_v']):.6f}; every replicate contained at least one strict cross-definition subgroup-order reversal.\n- Mixed-order mechanism: population ΔV = {float(ref['mixed_order']['population_delta_cramers_v']):.6f}; the strict-reversal probability was {float(ref['mixed_order']['probability_any_strict_reversal']):.4f}.\n- Null mechanism: both population associations were zero. Non-zero sample disagreement under this mechanism is sampling-induced ordering instability around population ties and must not be described as a substantive population reversal.\n\n## Observation-process stress tests\n\nFor the rank-reversal mechanism at n = 250 per group and balanced allocation, 10 per cent active/project swapping preserved the broad level and broad association exactly under no missingness, while changing the active-use association enough to move the mean observed ΔV from {float(obs[('rank_reversal','none','none')]['mean_delta_cramers_v']):.6f} to {float(obs[('rank_reversal','active_project_swap_10','none')]['mean_delta_cramers_v']):.6f}. In contrast, project/other swapping crossed the broad-outcome boundary and produced mean broad-association observation error of {float(obs[('rank_reversal','project_other_swap_10','none')]['mean_broad_association_observation_error']):.6f}.\n\n## Permitted conclusion\n\nThe simulation supports the narrow conclusion that, under controlled finite categorical state structures, defensible nested definitions can preserve level monotonicity while changing association strength, subgroup order and the composition and wording of admissible claims. It does not identify a universally correct definition, establish empirical prevalence or prove improved managerial decision quality.\n'''
    (output/'IM_R4_RESULT_SUMMARY_EN.md').write_text(summary,encoding='utf-8')
    warning=warnings[0] if warnings else None
    hostile=f'''# Audit ostil IM-R4 — rezultate şi limite\n\n## Verdict\n\n**Motorul şi execuţia trec poarta tehnică, dar articolul rămâne NO-GO pentru submission.** Simularea elimină motivul rezonabil de critică potrivit căruia ODSA ar fi doar o recodificare ilustrată printr-un singur eşantion. Ea nu elimină necesitatea Study 2, problema etică ori riscul ca reviewerul să considere claim-admissibility o regulă semantică prea dependentă de judecata cercetătorului.\n\n## Rezultate care rezistă unui evaluator ostil\n\n1. Monotonicitatea nivelului a fost respectată în toate cele 1.728.000 de replicări.\n2. Semnul contrastului de asociere nu este determinat de nesting: mecanismele îngheţate produc atât ΔV pozitiv, cât şi negativ şi zero la nivel de populaţie.\n3. Un mecanism prespecificat produce o inversare strictă a ordinii grupurilor sub definiţia îngustă faţă de cea largă.\n4. Misclassification în interiorul clasei broad poate modifica narrow outcome fără să schimbe broad boundary, în timp ce misclassification care traversează graniţa poate modifica şi broad outcome.\n5. Separarea population, sampled true şi observed permite atribuirea distinctă a erorii de eşantionare şi a erorii procesului de observare.\n\n## Vulnerabilităţi rămase\n\n- Simularea principală foloseşte trei stări, trei grupuri şi o familie nested. Generalitatea pentru definiţii non-nested este susţinută prin identităţi şi contraexemple, nu prin programul factorial principal.\n- Misclassification este nondiferenţială şi fixată la 10%; nu sunt simulate erori dependente simultan de grup şi stare.\n- Missingness este limitată la două mecanisme, fără non-ignorability bazată pe variabile neobservate.\n- Cramér’s V este ne-negativ şi are upward finite-sample bias când parametrul populaţiei este zero; de aceea contrastul observat este tras către zero în scenariile project-only şi compensating.\n- Reversal-urile observate când o definiţie are population ties reprezintă instabilitate de ranking indusă de eşantionare, nu reversări de populaţie.\n- Frecvenţele Monte Carlo sunt condiţionate de design şi nu sunt legi ale ODSA.\n- Nu există dovadă că prezentarea ODSA îmbunătăţeşte deciziile manageriale.\n- Study 2 rămâne obligatoriu pentru a evita impresia că metoda a fost construită pentru itemul românesc.\n\n## Convergenţă\n\nAu fost efectuate {convergence['comparison_count']} comparaţii stream–pool. A existat {convergence['warning_count']} avertisment şi zero eşecuri. Avertismentul izolat a avut deviaţia standardizată maximă {convergence['maximum_standardised_stream_deviation']:.6f}''' + (f''' în celula {warning['cell_id']} ({warning['scenario']}, n={warning['sample_size_per_group']}, {warning['allocation_profile']}, {warning['misclassification_profile']}, {warning['missingness_profile']}) pentru {warning['metric']}. Nu apare un pattern de instabilitate, iar rularea completă independentă a fost byte-identical.''' if warning else '.') + '''\n\n## Verdict de etapă\n\n```text\nfull-engine conformance: PASS\nfour-stream execution: PASS\nindependent byte-identical rerun: PASS\nhostile result audit: CONDITIONAL GO\nStudy 2: ABSENT\nethics determination: UNRESOLVED\nInformation & Management submission: NO-GO\n```\n'''
    (output/'IM_R4_HOSTILE_RESULT_AUDIT_RO.md').write_text(hostile,encoding='utf-8')
    return gate_payload

def main():
 p=argparse.ArgumentParser(); p.add_argument('--full-dir',type=Path,required=True); p.add_argument('--output',type=Path,required=True); p.add_argument('--repro-check',type=Path); a=p.parse_args(); print(json.dumps(build(a.full_dir,a.output,a.repro_check),indent=2,sort_keys=True))
if __name__=='__main__':main()
